style.css:
@-moz-document domain("pinterest.com") {
body {
    background: linear-gradient(to bottom, #87ceeb, #ffffff) no-repeat center center fixed,
                url("https://i.ibb.co/THQZKFp/flowers-water-sky.jpg") no-repeat center center fixed;
    background-size: cover;
    color: #0d3b66 !important;
    font-family: 'Helvetica Neue', sans-serif !important;
  }

  a, a:visited {
    color: #1565c0 !important;
  }

  header, nav, footer, div[data-test-id="header"], div[data-test-id="board-header"] {
    background: rgba(255, 255, 255, 0.6) !important;
    backdrop-filter: blur(8px);
  }

  input, textarea, button {
    background: rgba(255, 255, 255, 0.8) !important;
    border: 1px solid #87ceeb !important;
    color: #0d3b66 !important;
  }

  div[data-test-id="pin"] {
    background: rgba(255, 255, 255, 0.85) !important;
    border-radius: 12px !important;
  }
}
